mapper.select:
SELECT *
FROM t_ddh_config_sync_history
WHERE cluster_id = #{clusterId}
  AND service_name = #{serviceName}
ORDER BY sync_start_time DESC

SELECT *
FROM t_ddh_config_sync_history
WHERE cluster_id = #{clusterId}
  AND sync_start_time BETWEEN #{startTime} AND #{endTime}
ORDER BY sync_start_time DESC

SELECT *
FROM t_ddh_config_sync_history
WHERE cluster_id = #{clusterId}
  AND sync_operation_type = #{operationType}
ORDER BY sync_start_time DESC
